package net.officefloor.hq.app.payment;

import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** A lump payment from a client, split across several of their invoices. */
@RestController
@RequestMapping("/api/clients/{clientId}/payments")
public class ClientPaymentController {

    private final PaymentService service;

    public ClientPaymentController(PaymentService service) {
        this.service = service;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ClientPaymentResponse record(@PathVariable Long clientId, @Valid @RequestBody ClientPaymentRequest request) {
        return service.recordForClient(clientId, request);
    }
}
package net.officefloor.hq.app.payment;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/**
 * Payload to record one lump payment from a client, split across their invoices. With {@code useCredit} the client's
 * credit (held deposits, then unused credit notes) is used up toward the invoices before the money received; any of
 * the money received that the invoices do not need is kept as credit for the client.
 */
public record ClientPaymentRequest(
        @NotNull @DecimalMin("0.01") @Digits(integer = 10, fraction = 2) BigDecimal amount,
        @NotNull LocalDate date,
        @NotEmpty List<@Valid @NotNull Allocation> allocations,
        Boolean useCredit) {

    public boolean usesCredit() {
        return Boolean.TRUE.equals(useCredit);
    }

    /** The share of the lump paid against one invoice. */
    public record Allocation(
            @NotNull Long invoiceId,
            @NotNull @DecimalMin("0.01") @Digits(integer = 10, fraction = 2) BigDecimal amount) {
    }
}
package net.officefloor.hq.app.payment;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A lump sum a client paid on a given day, split across several of their invoices. It may also use up the client's
 * credit first (held deposits, then unused credit notes); whatever of the money received is not needed is kept as
 * credit for the client.
 */
@Entity
@Table(name = "client_payment")
public class ClientPayment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "client_id", nullable = false)
    private Long clientId;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "paid_date", nullable = false)
    private LocalDate date;

    /** Held deposits used up toward the invoices along with the money received. */
    @Column(name = "from_deposits", nullable = false, precision = 12, scale = 2)
    private BigDecimal fromDeposits = BigDecimal.ZERO.setScale(2);

    /** Unused credit notes used up toward the invoices along with the money received. */
    @Column(name = "from_credit_notes", nullable = false, precision = 12, scale = 2)
    private BigDecimal fromCreditNotes = BigDecimal.ZERO.setScale(2);

    /** Money received beyond what the invoices needed, kept as credit for the client. */
    @Column(name = "to_credit", nullable = false, precision = 12, scale = 2)
    private BigDecimal toCredit = BigDecimal.ZERO.setScale(2);

    protected ClientPayment() {
    }

    public ClientPayment(Long clientId, BigDecimal amount, LocalDate date) {
        this.clientId = clientId;
        this.amount = amount.setScale(2);
        this.date = date;
    }

    public ClientPayment(Long clientId, BigDecimal amount, LocalDate date, BigDecimal fromDeposits,
            BigDecimal fromCreditNotes, BigDecimal toCredit) {
        this(clientId, amount, date);
        this.fromDeposits = fromDeposits.setScale(2);
        this.fromCreditNotes = fromCreditNotes.setScale(2);
        this.toCredit = toCredit.setScale(2);
    }

    public Long getId() {
        return id;
    }

    public Long getClientId() {
        return clientId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public BigDecimal getFromDeposits() {
        return fromDeposits;
    }

    public BigDecimal getFromCreditNotes() {
        return fromCreditNotes;
    }

    public BigDecimal getToCredit() {
        return toCredit;
    }
}
package net.officefloor.hq.app.payment;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** An amount a client has paid against an invoice on a given day. */
@Entity
@Table(name = "payment")
public class Payment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "invoice_id", nullable = false)
    private Long invoiceId;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "paid_date", nullable = false)
    private LocalDate date;

    /** The lump payment this was split from; null when paid against the invoice on its own. */
    @Column(name = "client_payment_id")
    private Long clientPaymentId;

    /** The deposit application this was put toward the invoice from; null when it was not paid from deposits. */
    @Column(name = "deposit_application_id")
    private Long depositApplicationId;

    protected Payment() {
    }

    public Payment(Long invoiceId, BigDecimal amount, LocalDate date) {
        this.invoiceId = invoiceId;
        this.amount = amount.setScale(2);
        this.date = date;
    }

    public Payment(Long invoiceId, BigDecimal amount, LocalDate date, Long clientPaymentId) {
        this(invoiceId, amount, date);
        this.clientPaymentId = clientPaymentId;
    }

    /** A share of a client's held deposits put toward an invoice. */
    public static Payment fromDeposits(Long invoiceId, BigDecimal amount, LocalDate date, Long depositApplicationId) {
        Payment payment = new Payment(invoiceId, amount, date);
        payment.depositApplicationId = depositApplicationId;
        return payment;
    }

    public Long getId() {
        return id;
    }

    public Long getInvoiceId() {
        return invoiceId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public Long getClientPaymentId() {
        return clientPaymentId;
    }

    public Long getDepositApplicationId() {
        return depositApplicationId;
    }
}
package net.officefloor.hq.app.payment;

import java.math.BigDecimal;
import java.time.Clock;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Function;
import java.util.function.Supplier;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.client.ClientRepository;
import net.officefloor.hq.app.credit.ClientCreditResponse;
import net.officefloor.hq.app.credit.ClientCreditService;
import net.officefloor.hq.app.creditnote.CreditNoteRepository;
import net.officefloor.hq.app.deposit.DepositApplication;
import net.officefloor.hq.app.deposit.DepositApplicationRepository;
import net.officefloor.hq.app.deposit.DepositApplicationRequest;
import net.officefloor.hq.app.deposit.DepositApplicationResponse;
import net.officefloor.hq.app.invoice.Invoice;
import net.officefloor.hq.app.invoice.InvoiceRepository;
import net.officefloor.hq.app.invoice.InvoiceStatus;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PaymentService {

    private final PaymentRepository payments;
    private final CreditNoteRepository creditNotes;
    private final InvoiceRepository invoices;
    private final ClientPaymentRepository clientPayments;
    private final DepositApplicationRepository depositApplications;
    private final ClientCreditService credit;
    private final ClientRepository clients;
    private final Clock clock;
    private final Audit audit;

    public PaymentService(PaymentRepository payments, CreditNoteRepository creditNotes, InvoiceRepository invoices,
            ClientPaymentRepository clientPayments, DepositApplicationRepository depositApplications,
            ClientCreditService credit, ClientRepository clients, Clock clock, Audit audit) {
        this.payments = payments;
        this.creditNotes = creditNotes;
        this.invoices = invoices;
        this.clientPayments = clientPayments;
        this.depositApplications = depositApplications;
        this.credit = credit;
        this.clients = clients;
        this.clock = clock;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<PaymentResponse> list(Long projectId, Long invoiceId) {
        find(projectId, invoiceId);
        return payments.findByInvoiceIdOrderByDateAscIdAsc(invoiceId).stream().map(PaymentResponse::from).toList();
    }

    /**
     * Records a payment against an invoice that has been sent to the client and is still owing, and
     * works out the invoice's status from what has now been paid and credited. A payment may not take
     * the total paid and credited beyond the invoice amount.
     */
    @Transactional
    public PaymentResponse record(Long projectId, Long invoiceId, PaymentRequest request) {
        Invoice invoice = find(projectId, invoiceId);
        return apply(invoice, request.amount(), () -> new Payment(invoice.getId(), request.amount(), request.date()));
    }

    /**
     * Records one lump payment from a client split across several of their owing invoices. With
     * {@code useCredit} the client's credit is used up first (held deposits, then unused credit
     * notes) and the money received covers the rest; otherwise the money received covers it all.
     * The shares may not add up to more than the money received plus any credit used, and whatever
     * of the money received is left over is kept as credit for the client, so the money received
     * plus the credit used always equals the shares plus what is kept. Each invoice may appear
     * once, and each share is recorded as a payment against its own invoice under the same rules
     * as a payment made on its own.
     */
    @Transactional
    public ClientPaymentResponse recordForClient(Long clientId, ClientPaymentRequest request) {
        requireClient(clientId);
        BigDecimal allocated = total(request.allocations(), ClientPaymentRequest.Allocation::amount).setScale(2);
        BigDecimal received = request.amount().setScale(2);
        BigDecimal fromDeposits = BigDecimal.ZERO.setScale(2);
        BigDecimal fromCreditNotes = BigDecimal.ZERO.setScale(2);
        if (request.usesCredit()) {
            ClientCreditResponse available = credit.available(clientId);
            fromDeposits = allocated.min(available.deposits());
            fromCreditNotes = allocated.subtract(fromDeposits).min(available.creditNotes());
        }
        BigDecimal fromReceived = allocated.subtract(fromDeposits).subtract(fromCreditNotes);
        if (fromReceived.compareTo(received) > 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, request.usesCredit()
                    ? "The shares add up to more than the payment and the credit available"
                    : "The shares add up to more than the payment");
        }
        BigDecimal toCredit = received.subtract(fromReceived);
        requireDistinct(request.allocations(), ClientPaymentRequest.Allocation::invoiceId);
        ClientPayment lump = clientPayments.saveAndFlush(new ClientPayment(clientId, received, request.date(),
                fromDeposits, fromCreditNotes, toCredit));
        List<PaymentResponse> shares = request.allocations().stream()
                .map(a -> apply(findForClient(clientId, a.invoiceId()), a.amount(),
                        () -> new Payment(a.invoiceId(), a.amount(), request.date(), lump.getId())))
                .toList();
        audit.record("CLIENT_PAYMENT_RECORDED id=" + lump.getId() + " client=" + clientId
                + " amount=" + lump.getAmount().toPlainString()
                + " fromDeposits=" + lump.getFromDeposits().toPlainString()
                + " fromCreditNotes=" + lump.getFromCreditNotes().toPlainString()
                + " toCredit=" + lump.getToCredit().toPlainString());
        return ClientPaymentResponse.from(lump, shares);
    }

    /**
     * Puts part of a client's held deposits toward several of their owing invoices, today. The
     * shares may not add up to more than is still held, each invoice may appear once, and each share
     * is recorded as a payment against its own invoice under the same rules as a lump payment's.
     */
    @Transactional
    public DepositApplicationResponse applyDeposits(Long clientId, DepositApplicationRequest request) {
        requireClient(clientId);
        BigDecimal allocated = total(request.allocations(), DepositApplicationRequest.Allocation::amount);
        BigDecimal held = credit.heldDeposits(clientId);
        if (allocated.compareTo(held) > 0) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "The shares add up to more than the deposits held");
        }
        requireDistinct(request.allocations(), DepositApplicationRequest.Allocation::invoiceId);
        LocalDate today = LocalDate.now(clock);
        DepositApplication application = depositApplications.saveAndFlush(
                new DepositApplication(clientId, allocated, today));
        List<PaymentResponse> shares = request.allocations().stream()
                .map(a -> apply(findForClient(clientId, a.invoiceId()), a.amount(),
                        () -> Payment.fromDeposits(a.invoiceId(), a.amount(), today, application.getId())))
                .toList();
        audit.record("DEPOSIT_APPLIED id=" + application.getId() + " client=" + clientId
                + " amount=" + application.getAmount().toPlainString());
        return DepositApplicationResponse.from(application, shares);
    }

    private void requireClient(Long clientId) {
        if (!clients.existsById(clientId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
        }
    }

    private static <A> BigDecimal total(List<A> allocations, Function<A, BigDecimal> amount) {
        return allocations.stream().map(amount).reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    private static <A> void requireDistinct(List<A> allocations, Function<A, Long> invoiceId) {
        Set<Long> seen = new HashSet<>();
        for (A a : allocations) {
            if (!seen.add(invoiceId.apply(a))) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Each invoice may be paid only once");
            }
        }
    }

    private PaymentResponse apply(Invoice invoice, BigDecimal amount, Supplier<Payment> payment) {
        if (invoice.getStatus() == InvoiceStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Send the invoice before recording a payment");
        }
        if (invoice.getStatus() == InvoiceStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been cancelled");
        }
        if (invoice.getStatus() == InvoiceStatus.WRITTEN_OFF) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been written off");
        }
        if (!invoice.getStatus().isOwing()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice is already paid");
        }
        BigDecimal paid = payments.sumAmountByInvoiceId(invoice.getId()).add(amount);
        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoice.getId());
        BigDecimal settled = paid.add(credited);
        if (settled.compareTo(invoice.getAmount()) > 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Payment is more than the balance due");
        }
        Payment saved = payments.saveAndFlush(payment.get());
        invoice.applySettledTotals(paid, credited);
        invoices.flush();
        audit.record("PAYMENT_RECORDED id=" + saved.getId() + " amount=" + saved.getAmount().toPlainString());
        return PaymentResponse.from(saved);
    }

    private Invoice findForClient(Long clientId, Long invoiceId) {
        return invoices.findById(invoiceId)
                .filter(i -> i.getProject().getClient().getId().equals(clientId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
    }

    private Invoice find(Long projectId, Long invoiceId) {
        return invoices.findById(invoiceId)
                .filter(i -> i.getProject().getId().equals(projectId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
    }
}
package net.officefloor.hq.app.payment;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/**
 * A lump payment from a client and the payment recorded against each invoice it was split across, with how much of
 * the client's credit it used up ({@code fromDeposits}, {@code fromCreditNotes}) and how much of the money received
 * was kept as credit for them ({@code toCredit}).
 */
public record ClientPaymentResponse(Long id, Long clientId, BigDecimal amount, LocalDate date,
        BigDecimal fromDeposits, BigDecimal fromCreditNotes, BigDecimal toCredit, List<PaymentResponse> allocations) {

    static ClientPaymentResponse from(ClientPayment lump, List<PaymentResponse> allocations) {
        return new ClientPaymentResponse(lump.getId(), lump.getClientId(), lump.getAmount(), lump.getDate(),
                lump.getFromDeposits(), lump.getFromCreditNotes(), lump.getToCredit(), allocations);
    }
}
import { MoneyPipe } from '../currencies/money.pipe';
import { HttpErrorResponse } from '@angular/common/http';
import { Component, computed, inject, input, output, signal } from '@angular/core';
import { Observable } from 'rxjs';
import { rxResource, toSignal } from '@angular/core/rxjs-interop';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { CreditService } from '../credit/credit.service';
import { DepositService } from '../deposits/deposit.service';
import { InvoiceService } from '../invoices/invoice.service';
import { PaymentService } from './payment.service';

const TWO_DECIMALS = /^\d+(\.\d{1,2})?$/;

/** Whole cents for an entered amount, or null when it is not a valid amount. */
function toCents(value: string | number): number | null {
  const trimmed = String(value).trim();
  return TWO_DECIMALS.test(trimmed) ? Math.round(Number(trimmed) * 100) : null;
}

/** Where the money split across the invoices comes from: a payment received now, or deposits already held. */
export type PaymentSource = 'payment' | 'deposit';

// Records one lump payment from a client and splits it across their invoices that are still owed.
// The client's credit (held deposits, then unused credit notes) can be used up first; the shares may
// add up to no more than the payment plus that credit, and whatever of the payment is left over is
// kept as credit for the client. With the deposit source it
// instead puts part of the client's held deposits toward those invoices, split the same way; the
// shares may not add up to more than is held.
@Component({
  selector: 'app-client-payment',
  imports: [MoneyPipe, ReactiveFormsModule],
  template: `
    <section aria-labelledby="client-payment-heading" data-testid="client-payment">
      <h2 id="client-payment-heading">{{ fromDeposit() ? 'Put a deposit toward invoices' : 'Record a payment' }}</h2>
      @if (statement.error() || (fromDeposit() && deposits.error()) || (useCredit() && credit.error())) {
        <p role="alert" data-testid="client-payment-load-error">Could not load the client's invoices.</p>
      } @else if (statement.hasValue() && (!fromDeposit() || deposits.hasValue())) {
        @if (owing().length === 0) {
          <p data-testid="client-payment-none-owing">This client has no invoices waiting to be paid.</p>
        } @else {
          <form [formGroup]="form" (ngSubmit)="submit()" data-testid="payment-form" novalidate>
            @if (fromDeposit()) {
              <p>
                Deposits held:
                <span data-testid="payment-deposit-held">{{ heldCents() / 100 | money: currency() }}</span>
              </p>
            } @else {
              <div>
                <label for="client-payment-amount">Amount received</label>
                <input
                  id="client-payment-amount"
                  type="number"
                  inputmode="decimal"
                  min="0.01"
                  step="0.01"
                  formControlName="amount"
                  data-testid="payment-form-amount"
                  [attr.aria-invalid]="invalid('amount')"
                  [attr.aria-describedby]="invalid('amount') ? 'client-payment-amount-error' : null"
                />
                @if (invalid('amount')) {
                  <p id="client-payment-amount-error" role="alert" data-testid="payment-form-amount-error">
                    Enter an amount greater than zero with at most two decimal places.
                  </p>
                }
              </div>
              <div>
                <label for="client-payment-date">Date paid</label>
                <input
                  id="client-payment-date"
                  type="date"
                  formControlName="date"
                  data-testid="payment-form-date"
                  [attr.aria-invalid]="invalid('date')"
                  [attr.aria-describedby]="invalid('date') ? 'client-payment-date-error' : null"
                />
                @if (invalid('date')) {
                  <p id="client-payment-date-error" role="alert" data-testid="payment-form-date-error">
                    Enter the date the payment was made.
                  </p>
                }
              </div>
              <div>
                <input
                  id="client-payment-use-credit"
                  type="checkbox"
                  data-testid="payment-use-credit"
                  [checked]="useCredit()"
                  (change)="useCredit.set($any($event.target).checked)"
                  aria-describedby="client-payment-credit-note"
                />
                <label for="client-payment-use-credit">Use the client's deposits and credit first</label>
                <p id="client-payment-credit-note">
                  @if (useCredit()) {
                    Credit available:
                    <span data-testid="payment-credit-available">{{ creditCents() / 100 | money: currency() }}</span>.
                  }
                  Any of the payment not allocated is kept as credit for the client.
                </p>
              </div>
            }
            <table data-testid="payment-alloc-table">
              <caption>Split the {{ fromDeposit() ? 'deposit' : 'payment' }} across the invoices still owed</caption>
              <thead>
                <tr>
                  <th scope="col">Invoice</th>
                  <th scope="col">Job</th>
                  <th scope="col">Balance due</th>
                  <th scope="col">Pay</th>
                </tr>
              </thead>
              <tbody>
                @for (i of owing(); track i.id) {
                  <tr [attr.data-testid]="'payment-alloc-row-' + i.id">
                    <td>#{{ i.id }}</td>
                    <td>{{ i.projectName }}</td>
                    <td data-testid="payment-alloc-due">{{ i.amountDue | money: currency() }}</td>
                    <td>
                      <input
                        type="number"
                        inputmode="decimal"
                        min="0"
                        step="0.01"
                        [attr.aria-label]="'Amount to pay on invoice ' + i.id"
                        [attr.data-testid]="'payment-alloc-' + i.id"
                        [value]="allocations()[i.id] ?? ''"
                        (input)="allocate(i.id, $any($event.target).value)"
                      />
                    </td>
                  </tr>
                }
              </tbody>
              <tfoot>
                <tr>
                  <th scope="row" colspan="3">Allocated</th>
                  <td data-testid="payment-alloc-total">{{ allocatedCents() / 100 | money: currency() }}</td>
                </tr>
                @if (!fromDeposit()) {
                  <tr>
                    <th scope="row" colspan="3">From credit</th>
                    <td data-testid="payment-from-credit">{{ fromCreditCents() / 100 | money: currency() }}</td>
                  </tr>
                  <tr>
                    <th scope="row" colspan="3">Kept as credit</th>
                    <td data-testid="payment-to-credit">{{ toCreditCents() / 100 | money: currency() }}</td>
                  </tr>
                }
              </tfoot>
            </table>
            <button type="submit" data-testid="payment-form-submit" [disabled]="saving()">
              {{ fromDeposit() ? 'Apply deposit' : 'Record payment' }}
            </button>
            @if (saveError()) {
              <p role="alert" data-testid="payment-form-error">{{ saveError() }}</p>
            }
          </form>
        }
      }
    </section>
  `,
})
export class ClientPaymentForm {
  private readonly invoices = inject(InvoiceService);
  private readonly payments = inject(PaymentService);
  private readonly depositService = inject(DepositService);
  private readonly creditService = inject(CreditService);
  private readonly money = new MoneyPipe();

  readonly clientId = input.required<number>();
  readonly source = input<PaymentSource>('payment');
  protected readonly fromDeposit = computed(() => this.source() === 'deposit');
  /** Emits once the payment has been recorded. */
  readonly recorded = output<void>();

  protected readonly statement = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.invoices.statementForClient(params),
  });

  /** The client's deposits, loaded only when they are the source of the money. */
  protected readonly deposits = rxResource({
    params: () => (this.fromDeposit() ? this.clientId() : undefined),
    stream: ({ params }) => this.depositService.list(params),
  });

  /** Whole cents of deposits still held for the client. */
  protected readonly heldCents = computed(() =>
    this.deposits.hasValue() ? Math.round(this.deposits.value().total * 100) : 0,
  );

  /** Whether the client's credit (held deposits, then unused credit notes) is used up before the payment. */
  protected readonly useCredit = signal(false);

  /** The client's credit, loaded only when a payment is to use it up. */
  protected readonly credit = rxResource({
    params: () => (!this.fromDeposit() && this.useCredit() ? this.clientId() : undefined),
    stream: ({ params }) => this.creditService.available(params),
  });

  /** Whole cents of credit the client has to spend, or zero when it is not being used. */
  protected readonly creditCents = computed(() =>
    !this.fromDeposit() && this.useCredit() && this.credit.hasValue() ? Math.round(this.credit.value().total * 100) : 0,
  );

  /** Whole cents of the allocations covered by the client's credit; it is used up before the payment. */
  protected readonly fromCreditCents = computed(() => Math.min(this.allocatedCents(), this.creditCents()));

  /** Whole cents of the payment left over once the allocations not covered by credit are paid; kept as credit. */
  protected readonly toCreditCents = computed(() =>
    Math.max(0, (toCents(this.amount()) ?? 0) - (this.allocatedCents() - this.fromCreditCents())),
  );

  /** The client's currency; the payment and its allocations are in it. */
