260	@Service
261	public class PaymentService {
262	
263	    private final PaymentRepository payments;
264	    private final CreditNoteRepository creditNotes;
265	    private final InvoiceRepository invoices;
266	    private final ClientPaymentRepository clientPayments;
267	    private final DepositApplicationRepository depositApplications;
268	    private final ClientCreditService credit;
269	    private final ClientRepository clients;
270	    private final Clock clock;
271	    private final Audit audit;
272	
273	    public PaymentService(PaymentRepository payments, CreditNoteRepository creditNotes, InvoiceRepository invoices,
274	            ClientPaymentRepository clientPayments, DepositApplicationRepository depositApplications,
275	            ClientCreditService credit, ClientRepository clients, Clock clock, Audit audit) {
276	        this.payments = payments;
277	        this.creditNotes = creditNotes;
278	        this.invoices = invoices;
279	        this.clientPayments = clientPayments;
280	        this.depositApplications = depositApplications;
281	        this.credit = credit;
282	        this.clients = clients;
283	        this.clock = clock;
284	        this.audit = audit;
285	    }
286	
287	    @Transactional(readOnly = true)
288	    public List<PaymentResponse> list(Long projectId, Long invoiceId) {
289	        find(projectId, invoiceId);
290	        return payments.findByInvoiceIdOrderByDateAscIdAsc(invoiceId).stream().map(PaymentResponse::from).toList();
291	    }
292	
293	    /**
294	     * Records a payment against an invoice that has been sent to the client and is still owing, and
295	     * works out the invoice's status from what has now been paid and credited. A payment may not take
296	     * the total paid and credited beyond the invoice amount.
297	     */
298	    @Transactional
299	    public PaymentResponse record(Long projectId, Long invoiceId, PaymentRequest request) {
300	        Invoice invoice = find(projectId, invoiceId);
301	        return apply(invoice, request.amount(), () -> new Payment(invoice.getId(), request.amount(), request.date()));
302	    }
303	
304	    /**
305	     * Records one lump payment from a client split across several of their owing invoices. With
306	     * {@code useCredit} the client's credit is used up first (held deposits, then unused credit
307	     * notes) and the money received covers the rest; otherwise the money received covers it all.
308	     * The shares may not add up to more than the money received plus any credit used, and whatever
309	     * of the money received is left over is kept as credit for the client, so the money received
310	     * plus the credit used always equals the shares plus what is kept. Each invoice may appear
311	     * once, and each share is recorded as a payment against its own invoice under the same rules
312	     * as a payment made on its own.
313	     */
314	    @Transactional
315	    public ClientPaymentResponse recordForClient(Long clientId, ClientPaymentRequest request) {
316	        requireClient(clientId);
317	        BigDecimal allocated = total(request.allocations(), ClientPaymentRequest.Allocation::amount).setScale(2);
318	        BigDecimal received = request.amount().setScale(2);
319	        BigDecimal fromDeposits = BigDecimal.ZERO.setScale(2);
320	        BigDecimal fromCreditNotes = BigDecimal.ZERO.setScale(2);
321	        if (request.usesCredit()) {
322	            ClientCreditResponse available = credit.available(clientId);
323	            fromDeposits = allocated.min(available.deposits());
324	            fromCreditNotes = allocated.subtract(fromDeposits).min(available.creditNotes());
325	        }
326	        BigDecimal fromReceived = allocated.subtract(fromDeposits).subtract(fromCreditNotes);
327	        if (fromReceived.compareTo(received) > 0) {
328	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, request.usesCredit()
329	                    ? "The shares add up to more than the payment and the credit available"
330	                    : "The shares add up to more than the payment");
331	        }
332	        BigDecimal toCredit = received.subtract(fromReceived);
333	        requireDistinct(request.allocations(), ClientPaymentRequest.Allocation::invoiceId);
334	        ClientPayment lump = clientPayments.saveAndFlush(new ClientPayment(clientId, received, request.date(),
335	                fromDeposits, fromCreditNotes, toCredit));
336	        List<PaymentResponse> shares = request.allocations().stream()
337	                .map(a -> apply(findForClient(clientId, a.invoiceId()), a.amount(),
338	                        () -> new Payment(a.invoiceId(), a.amount(), request.date(), lump.getId())))
339	                .toList();
340	        audit.record("CLIENT_PAYMENT_RECORDED id=" + lump.getId() + " client=" + clientId
341	                + " amount=" + lump.getAmount().toPlainString()
342	                + " fromDeposits=" + lump.getFromDeposits().toPlainString()
343	                + " fromCreditNotes=" + lump.getFromCreditNotes().toPlainString()
344	                + " toCredit=" + lump.getToCredit().toPlainString());
345	        return ClientPaymentResponse.from(lump, shares);
346	    }
347	
348	    /**
349	     * Puts part of a client's held deposits toward several of their owing invoices, today. The
350	     * shares may not add up to more than is still held, each invoice may appear once, and each share
351	     * is recorded as a payment against its own invoice under the same rules as a lump payment's.
352	     */
353	    @Transactional
354	    public DepositApplicationResponse applyDeposits(Long clientId, DepositApplicationRequest request) {
355	        requireClient(clientId);
356	        BigDecimal allocated = total(request.allocations(), DepositApplicationRequest.Allocation::amount);
357	        BigDecimal held = credit.heldDeposits(clientId);
358	        if (allocated.compareTo(held) > 0) {
359	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
360	                    "The shares add up to more than the deposits held");
361	        }
362	        requireDistinct(request.allocations(), DepositApplicationRequest.Allocation::invoiceId);
363	        LocalDate today = LocalDate.now(clock);
364	        DepositApplication application = depositApplications.saveAndFlush(
365	                new DepositApplication(clientId, allocated, today));
366	        List<PaymentResponse> shares = request.allocations().stream()
367	                .map(a -> apply(findForClient(clientId, a.invoiceId()), a.amount(),
368	                        () -> Payment.fromDeposits(a.invoiceId(), a.amount(), today, application.getId())))
369	                .toList();
370	        audit.record("DEPOSIT_APPLIED id=" + application.getId() + " client=" + clientId
371	                + " amount=" + application.getAmount().toPlainString());
372	        return DepositApplicationResponse.from(application, shares);
373	    }
374	
375	    private void requireClient(Long clientId) {
376	        if (!clients.existsById(clientId)) {
377	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
378	        }
379	    }
380	
381	    private static <A> BigDecimal total(List<A> allocations, Function<A, BigDecimal> amount) {
382	        return allocations.stream().map(amount).reduce(BigDecimal.ZERO, BigDecimal::add);
383	    }
384	
385	    private static <A> void requireDistinct(List<A> allocations, Function<A, Long> invoiceId) {
386	        Set<Long> seen = new HashSet<>();
387	        for (A a : allocations) {
388	            if (!seen.add(invoiceId.apply(a))) {
389	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Each invoice may be paid only once");
390	            }
391	        }
392	    }
393	
394	    private PaymentResponse apply(Invoice invoice, BigDecimal amount, Supplier<Payment> payment) {
395	        if (invoice.getStatus() == InvoiceStatus.DRAFT) {
396	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Send the invoice before recording a payment");
397	        }
398	        if (invoice.getStatus() == InvoiceStatus.VOID) {
399	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been cancelled");
400	        }
401	        if (invoice.getStatus() == InvoiceStatus.WRITTEN_OFF) {
402	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been written off");
403	        }
404	        if (!invoice.getStatus().isOwing()) {
405	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice is already paid");
406	        }
407	        BigDecimal paid = payments.sumAmountByInvoiceId(invoice.getId()).add(amount);
408	        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoice.getId());
409	        BigDecimal settled = paid.add(credited);
410	        if (settled.compareTo(invoice.getAmount()) > 0) {
411	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Payment is more than the balance due");
412	        }
413	        Payment saved = payments.saveAndFlush(payment.get());
414	        invoice.applySettledTotals(paid, credited);
415	        invoices.flush();
416	        audit.record("PAYMENT_RECORDED id=" + saved.getId() + " amount=" + saved.getAmount().toPlainString());
417	        return PaymentResponse.from(saved);
418	    }
419	
420	    private Invoice findForClient(Long clientId, Long invoiceId) {
421	        return invoices.findById(invoiceId)
422	                .filter(i -> i.getProject().getClient().getId().equals(clientId))
423	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
424	    }
425	
426	    private Invoice find(Long projectId, Long invoiceId) {
427	        return invoices.findById(invoiceId)
428	                .filter(i -> i.getProject().getId().equals(projectId))
429	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
430	    }
431	}
