492	            @if (fromDeposit()) {
493	              <p>
494	                Deposits held:
495	                <span data-testid="payment-deposit-held">{{ heldCents() / 100 | money: currency() }}</span>
496	              </p>
497	            } @else {
498	              <div>
499	                <label for="client-payment-amount">Amount received</label>
500	                <input
501	                  id="client-payment-amount"
502	                  type="number"
503	                  inputmode="decimal"
504	                  min="0.01"
505	                  step="0.01"
506	                  formControlName="amount"
507	                  data-testid="payment-form-amount"
508	                  [attr.aria-invalid]="invalid('amount')"
509	                  [attr.aria-describedby]="invalid('amount') ? 'client-payment-amount-error' : null"
510	                />
511	                @if (invalid('amount')) {
512	                  <p id="client-payment-amount-error" role="alert" data-testid="payment-form-amount-error">
513	                    Enter an amount greater than zero with at most two decimal places.
514	                  </p>
515	                }
516	              </div>
517	              <div>
518	                <label for="client-payment-date">Date paid</label>
519	                <input
520	                  id="client-payment-date"
521	                  type="date"
522	                  formControlName="date"
523	                  data-testid="payment-form-date"
524	                  [attr.aria-invalid]="invalid('date')"
525	                  [attr.aria-describedby]="invalid('date') ? 'client-payment-date-error' : null"
526	                />
527	                @if (invalid('date')) {
528	                  <p id="client-payment-date-error" role="alert" data-testid="payment-form-date-error">
529	                    Enter the date the payment was made.
530	                  </p>
531	                }
532	              </div>
533	              <div>
534	                <input
535	                  id="client-payment-use-credit"
536	                  type="checkbox"
537	                  data-testid="payment-use-credit"
538	                  [checked]="useCredit()"
539	                  (change)="useCredit.set($any($event.target).checked)"
540	                  aria-describedby="client-payment-credit-note"
541	                />
542	                <label for="client-payment-use-credit">Use the client's deposits and credit first</label>
543	                <p id="client-payment-credit-note">
544	                  @if (useCredit()) {
545	                    Credit available:
546	                    <span data-testid="payment-credit-available">{{ creditCents() / 100 | money: currency() }}</span>.
547	                  }
548	                  Any of the payment not allocated is kept as credit for the client.
549	                </p>
550	              </div>
551	            }
552	            <table data-testid="payment-alloc-table">
553	              <caption>Split the {{ fromDeposit() ? 'deposit' : 'payment' }} across the invoices still owed</caption>
554	              <thead>
555	                <tr>
556	                  <th scope="col">Invoice</th>
557	                  <th scope="col">Job</th>
558	                  <th scope="col">Balance due</th>
559	                  <th scope="col">Pay</th>
560	                </tr>
561	              </thead>
562	              <tbody>
563	                @for (i of owing(); track i.id) {
564	                  <tr [attr.data-testid]="'payment-alloc-row-' + i.id">
565	                    <td>#{{ i.id }}</td>
566	                    <td>{{ i.projectName }}</td>
567	                    <td data-testid="payment-alloc-due">{{ i.amountDue | money: currency() }}</td>
568	                    <td>
569	                      <input
570	                        type="number"
571	                        inputmode="decimal"
572	                        min="0"
573	                        step="0.01"
574	                        [attr.aria-label]="'Amount to pay on invoice ' + i.id"
575	                        [attr.data-testid]="'payment-alloc-' + i.id"
576	                        [value]="allocations()[i.id] ?? ''"
577	                        (input)="allocate(i.id, $any($event.target).value)"
578	                      />
579	                    </td>
580	                  </tr>
581	                }
582	              </tbody>
583	              <tfoot>
584	                <tr>
585	                  <th scope="row" colspan="3">Allocated</th>
586	                  <td data-testid="payment-alloc-total">{{ allocatedCents() / 100 | money: currency() }}</td>
587	                </tr>
588	                @if (!fromDeposit()) {
