590	                    <th scope="row" colspan="3">From credit</th>
591	                    <td data-testid="payment-from-credit">{{ fromCreditCents() / 100 | money: currency() }}</td>
592	                  </tr>
593	                  <tr>
594	                    <th scope="row" colspan="3">Kept as credit</th>
595	                    <td data-testid="payment-to-credit">{{ toCreditCents() / 100 | money: currency() }}</td>
596	                  </tr>
597	                }
598	              </tfoot>
599	            </table>
600	            <button type="submit" data-testid="payment-form-submit" [disabled]="saving()">
601	              {{ fromDeposit() ? 'Apply deposit' : 'Record payment' }}
602	            </button>
603	            @if (saveError()) {
604	              <p role="alert" data-testid="payment-form-error">{{ saveError() }}</p>
605	            }
606	          </form>
607	        }
608	      }
609	    </section>
610	  `,
