612	export class ClientPaymentForm {
613	  private readonly invoices = inject(InvoiceService);
614	  private readonly payments = inject(PaymentService);
615	  private readonly depositService = inject(DepositService);
616	  private readonly creditService = inject(CreditService);
617	  private readonly money = new MoneyPipe();
618	
619	  readonly clientId = input.required<number>();
620	  readonly source = input<PaymentSource>('payment');
621	  protected readonly fromDeposit = computed(() => this.source() === 'deposit');
622	  /** Emits once the payment has been recorded. */
623	  readonly recorded = output<void>();
624	
625	  protected readonly statement = rxResource({
626	    params: () => this.clientId(),
627	    stream: ({ params }) => this.invoices.statementForClient(params),
628	  });
629	
630	  /** The client's deposits, loaded only when they are the source of the money. */
631	  protected readonly deposits = rxResource({
632	    params: () => (this.fromDeposit() ? this.clientId() : undefined),
633	    stream: ({ params }) => this.depositService.list(params),
634	  });
635	
636	  /** Whole cents of deposits still held for the client. */
637	  protected readonly heldCents = computed(() =>
638	    this.deposits.hasValue() ? Math.round(this.deposits.value().total * 100) : 0,
639	  );
640	
641	  /** Whether the client's credit (held deposits, then unused credit notes) is used up before the payment. */
642	  protected readonly useCredit = signal(false);
643	
644	  /** The client's credit, loaded only when a payment is to use it up. */
645	  protected readonly credit = rxResource({
646	    params: () => (!this.fromDeposit() && this.useCredit() ? this.clientId() : undefined),
647	    stream: ({ params }) => this.creditService.available(params),
648	  });
649	
650	  /** Whole cents of credit the client has to spend, or zero when it is not being used. */
651	  protected readonly creditCents = computed(() =>
652	    !this.fromDeposit() && this.useCredit() && this.credit.hasValue() ? Math.round(this.credit.value().total * 100) : 0,
653	  );
654	
655	  /** Whole cents of the allocations covered by the client's credit; it is used up before the payment. */
656	  protected readonly fromCreditCents = computed(() => Math.min(this.allocatedCents(), this.creditCents()));
657	
658	  /** Whole cents of the payment left over once the allocations not covered by credit are paid; kept as credit. */
659	  protected readonly toCreditCents = computed(() =>
660	    Math.max(0, (toCents(this.amount()) ?? 0) - (this.allocatedCents() - this.fromCreditCents())),
661	  );
662	
663	  /** The client's currency; the payment and its allocations are in it. */
664	  protected readonly currency = computed(() => (this.statement.hasValue() ? this.statement.value().currency : 'USD'));
665	
666	  /** The client's sent invoices that still have something left to pay. */
667	  protected readonly owing = computed(() =>
668	    (this.statement.hasValue() ? this.statement.value().invoices : []).filter(
669	      (i) => (i.status === 'SENT' || i.status === 'PARTIAL') && i.amountDue > 0,
670	    ),
671	  );
672	
673	  /** What has been typed against each invoice, keyed by invoice id. */
674	  protected readonly allocations = signal<Record<number, string>>({});
675	
676	  protected readonly allocatedCents = computed(() =>
677	    Object.values(this.allocations()).reduce((sum, v) => sum + (toCents(v) ?? 0), 0),
678	  );
679	
680	  protected readonly saving = signal(false);
681	  /** Settles once the payment being saved has been recorded or refused; null when nothing is being saved. */
682	  private inFlight: Promise<void> | null = null;
683	  protected readonly saveError = signal<string | null>(null);
684	
685	  protected readonly form = inject(NonNullableFormBuilder).group({
686	    amount: ['', [Validators.required, Validators.min(0.01), Validators.pattern(TWO_DECIMALS)]],
687	    date: ['', [Validators.required]],
688	  });
689	
690	  /** The amount received as typed, as a signal so what is kept as credit follows it. */
691	  private readonly amount = toSignal(this.form.controls.amount.valueChanges, { initialValue: '' });
692	
693	  protected invalid(name: 'amount' | 'date'): boolean {
694	    const control = this.form.controls[name];
695	    return control.invalid && (control.touched || control.dirty);
696	  }
697	
698	  protected allocate(invoiceId: number, value: string): void {
699	    this.allocations.update((a) => ({ ...a, [invoiceId]: value }));
700	  }
701	
702	  protected submit(): void {
703	    this.saveError.set(null);
704	    if (!this.fromDeposit() && this.form.invalid) {
705	      this.form.markAllAsTouched();
706	      return;
707	    }
708	    const shares: { invoiceId: number; amount: number }[] = [];
709	    for (const invoice of this.owing()) {
710	      const entered = (this.allocations()[invoice.id] ?? '').trim();
711	      if (entered === '') {
712	        continue;
713	      }
714	      const cents = toCents(entered);
715	      if (cents === null) {
716	        this.saveError.set(`Enter the amount for invoice #${invoice.id} with at most two decimal places.`);
717	        return;
718	      }
719	      if (cents > Math.round(invoice.amountDue * 100)) {
720	        this.saveError.set(`The amount for invoice #${invoice.id} is more than its balance due.`);
721	        return;
722	      }
723	      if (cents > 0) {
724	        shares.push({ invoiceId: invoice.id, amount: cents / 100 });
725	      }
726	    }
727	    if (shares.length === 0) {
728	      this.saveError.set(`Allocate the ${this.fromDeposit() ? 'deposit' : 'payment'} to at least one invoice.`);
729	      return;
730	    }
731	    const { amount, date } = this.form.getRawValue();
732	    const totalCents = toCents(amount) ?? 0;
733	    if (this.fromDeposit() && this.allocatedCents() > this.heldCents()) {
734	      this.saveError.set(
735	        `The amounts allocated add up to ${this.format(this.allocatedCents())}, ` +
736	          `but only ${this.format(this.heldCents())} is held in deposits.`,
737	      );
738	      return;
739	    }
740	    if (!this.fromDeposit() && this.useCredit() && !this.credit.hasValue()) {
741	      this.saveError.set('The client’s credit is still loading. Please try again.');
742	      return;
743	    }
744	    if (!this.fromDeposit() && this.allocatedCents() - this.fromCreditCents() > totalCents) {
745	      this.saveError.set(
746	        `The amounts allocated add up to ${this.format(this.allocatedCents())}, ` +
747	          `but the payment is ${this.format(totalCents)}` +
748	          (this.useCredit() ? ` and the credit available is ${this.format(this.creditCents())}.` : '.'),
749	      );
750	      return;
751	    }
752	    this.saving.set(true);
753	    let settle!: () => void;
754	    this.inFlight = new Promise((resolve) => (settle = resolve));
755	    const done = () => {
756	      this.inFlight = null;
757	      settle();
758	    };
759	    const request: Observable<unknown> = this.fromDeposit()
760	      ? this.depositService.apply(this.clientId(), { allocations: shares })
761	      : this.payments.recordForClient(this.clientId(), {
762	          amount: totalCents / 100,
763	          date,
764	          allocations: shares,
765	          useCredit: this.useCredit(),
766	        });
767	    request.subscribe({
768	      next: () => {
769	        this.saving.set(false);
770	        done();
771	        this.form.reset();
772	        this.allocations.set({});
773	        this.useCredit.set(false);
774	        this.statement.reload();
775	        if (this.fromDeposit()) {
776	          this.deposits.reload();
777	        }
778	        this.recorded.emit();
779	      },
780	      error: (err: HttpErrorResponse) => {
781	        this.saveError.set(
782	          err.status === 409
783	            ? 'One of the amounts is more than that invoice’s balance due.'
784	            : err.status === 400
785	              ? this.fromDeposit()
786	                ? 'The amounts allocated add up to more than the deposits held.'
787	                : 'The amounts allocated add up to more than the payment and any credit used.'
788	              : `Could not ${this.fromDeposit() ? 'apply the deposit' : 'record the payment'}. Please try again.`,
789	        );
790	        this.saving.set(false);
791	        done();
792	      },
793	    });
794	  }
795	
796	  /** Resolves once any payment being saved has been recorded or refused, so leaving the page does not race it. */
797	  settled(): Promise<void> {
798	    return this.inFlight ?? Promise.resolve();
799	  }
800	
801	  private format(cents: number): string {
802	    return this.money.transform(cents / 100, this.currency()) ?? '';
803	  }
804	}
805	import { HttpClient } from '@angular/common/http';
806	import { Injectable, inject } from '@angular/core';
807	import { Observable } from 'rxjs';
808	
809	/** Money a client has paid against an invoice. */
810	export interface Payment {
811	  id: number;
812	  invoiceId: number;
813	  amount: number;
814	  /** ISO date (yyyy-MM-dd) the payment was made. */
815	  date: string;
816	}
817	
818	export interface NewPayment {
819	  amount: number;
820	  date: string;
821	}
822	
823	/**
824	 * A lump payment from a client, split across several of their invoices. With `useCredit` the client's credit is used
825	 * up first; the shares may add up to no more than the amount plus any credit used, and the rest is kept as credit.
826	 */
827	export interface NewClientPayment {
828	  amount: number;
829	  date: string;
830	  allocations: { invoiceId: number; amount: number }[];
831	  useCredit: boolean;
832	}
833	
834	/** A recorded lump payment, the credit it used up, what was kept as credit, and the payment it made against each invoice. */
835	export interface ClientPayment {
836	  id: number;
837	  clientId: number;
838	  amount: number;
839	  date: string;
840	  fromDeposits: number;
841	  fromCreditNotes: number;
842	  toCredit: number;
843	  allocations: Payment[];
844	}
845	
846	@Injectable({ providedIn: 'root' })
847	export class PaymentService {
848	  private readonly http = inject(HttpClient);
849	
850	  /** An invoice's payments, oldest first. */
851	  list(projectId: number, invoiceId: number): Observable<Payment[]> {
852	    return this.http.get<Payment[]>(`/api/projects/${projectId}/invoices/${invoiceId}/payments`);
853	  }
854	
855	  record(projectId: number, invoiceId: number, payment: NewPayment): Observable<Payment> {
856	    return this.http.post<Payment>(`/api/projects/${projectId}/invoices/${invoiceId}/payments`, payment);
857	  }
858	
859	  /** Records one lump payment from a client, split across the given invoices. */
860	  recordForClient(clientId: number, payment: NewClientPayment): Observable<ClientPayment> {
861	    return this.http.post<ClientPayment>(`/api/clients/${clientId}/payments`, payment);
862	  }
863	}
