export class ClientPaymentForm {
  private readonly invoices = inject(InvoiceService);
  private readonly payments = inject(PaymentService);
  private readonly depositService = inject(DepositService);
  private readonly creditService = inject(CreditService);
  private readonly money = new MoneyPipe();

  readonly clientId = input.required<number>();
  readonly source = input<PaymentSource>('payment');
  protected readonly fromDeposit = computed(() => this.source() === 'deposit');
  /** Emits once the payment has been recorded. */
  readonly recorded = output<void>();

  protected readonly statement = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.invoices.statementForClient(params),
  });

  /** The client's deposits, loaded only when they are the source of the money. */
  protected readonly deposits = rxResource({
    params: () => (this.fromDeposit() ? this.clientId() : undefined),
    stream: ({ params }) => this.depositService.list(params),
  });

  /** Whole cents of deposits still held for the client. */
  protected readonly heldCents = computed(() =>
    this.deposits.hasValue() ? Math.round(this.deposits.value().total * 100) : 0,
  );

  /** Whether the client's credit (held deposits, then unused credit notes) is used up before the payment. */
  protected readonly useCredit = signal(false);

  /** The client's credit, loaded only when a payment is to use it up. */
  protected readonly credit = rxResource({
    params: () => (!this.fromDeposit() && this.useCredit() ? this.clientId() : undefined),
    stream: ({ params }) => this.creditService.available(params),
  });

  /** Whole cents of credit the client has to spend, or zero when it is not being used. */
  protected readonly creditCents = computed(() =>
    !this.fromDeposit() && this.useCredit() && this.credit.hasValue() ? Math.round(this.credit.value().total * 100) : 0,
  );

  /** Whole cents of the allocations covered by the client's credit; it is used up before the payment. */
  protected readonly fromCreditCents = computed(() => Math.min(this.allocatedCents(), this.creditCents()));

  /** Whole cents of the payment left over once the allocations not covered by credit are paid; kept as credit. */
  protected readonly toCreditCents = computed(() =>
    Math.max(0, (toCents(this.amount()) ?? 0) - (this.allocatedCents() - this.fromCreditCents())),
  );

  /** The client's currency; the payment and its allocations are in it. */
  protected readonly currency = computed(() => (this.statement.hasValue() ? this.statement.value().currency : 'USD'));

  /** The client's sent invoices that still have something left to pay. */
  protected readonly owing = computed(() =>
    (this.statement.hasValue() ? this.statement.value().invoices : []).filter(
      (i) => (i.status === 'SENT' || i.status === 'PARTIAL') && i.amountDue > 0,
    ),
  );

  /** What has been typed against each invoice, keyed by invoice id. */
  protected readonly allocations = signal<Record<number, string>>({});

  protected readonly allocatedCents = computed(() =>
    Object.values(this.allocations()).reduce((sum, v) => sum + (toCents(v) ?? 0), 0),
  );

  protected readonly saving = signal(false);
  /** Settles once the payment being saved has been recorded or refused; null when nothing is being saved. */
  private inFlight: Promise<void> | null = null;
  protected readonly saveError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    amount: ['', [Validators.required, Validators.min(0.01), Validators.pattern(TWO_DECIMALS)]],
    date: ['', [Validators.required]],
  });

  /** The amount received as typed, as a signal so what is kept as credit follows it. */
  private readonly amount = toSignal(this.form.controls.amount.valueChanges, { initialValue: '' });

  protected invalid(name: 'amount' | 'date'): boolean {
    const control = this.form.controls[name];
    return control.invalid && (control.touched || control.dirty);
  }

  protected allocate(invoiceId: number, value: string): void {
    this.allocations.update((a) => ({ ...a, [invoiceId]: value }));
  }

  protected submit(): void {
    this.saveError.set(null);
    if (!this.fromDeposit() && this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    const shares: { invoiceId: number; amount: number }[] = [];
    for (const invoice of this.owing()) {
      const entered = (this.allocations()[invoice.id] ?? '').trim();
      if (entered === '') {
        continue;
      }
      const cents = toCents(entered);
      if (cents === null) {
        this.saveError.set(`Enter the amount for invoice #${invoice.id} with at most two decimal places.`);
        return;
      }
      if (cents > Math.round(invoice.amountDue * 100)) {
        this.saveError.set(`The amount for invoice #${invoice.id} is more than its balance due.`);
        return;
      }
      if (cents > 0) {
        shares.push({ invoiceId: invoice.id, amount: cents / 100 });
      }
    }
    if (shares.length === 0) {
      this.saveError.set(`Allocate the ${this.fromDeposit() ? 'deposit' : 'payment'} to at least one invoice.`);
      return;
    }
    const { amount, date } = this.form.getRawValue();
    const totalCents = toCents(amount) ?? 0;
    if (this.fromDeposit() && this.allocatedCents() > this.heldCents()) {
      this.saveError.set(
        `The amounts allocated add up to ${this.format(this.allocatedCents())}, ` +
          `but only ${this.format(this.heldCents())} is held in deposits.`,
      );
      return;
    }
    if (!this.fromDeposit() && this.useCredit() && !this.credit.hasValue()) {
      this.saveError.set('The client’s credit is still loading. Please try again.');
      return;
    }
    if (!this.fromDeposit() && this.allocatedCents() - this.fromCreditCents() > totalCents) {
      this.saveError.set(
        `The amounts allocated add up to ${this.format(this.allocatedCents())}, ` +
          `but the payment is ${this.format(totalCents)}` +
          (this.useCredit() ? ` and the credit available is ${this.format(this.creditCents())}.` : '.'),
      );
      return;
    }
    this.saving.set(true);
    let settle!: () => void;
    this.inFlight = new Promise((resolve) => (settle = resolve));
    const done = () => {
      this.inFlight = null;
      settle();
    };
    const request: Observable<unknown> = this.fromDeposit()
      ? this.depositService.apply(this.clientId(), { allocations: shares })
      : this.payments.recordForClient(this.clientId(), {
          amount: totalCents / 100,
          date,
          allocations: shares,
          useCredit: this.useCredit(),
        });
    request.subscribe({
      next: () => {
        this.saving.set(false);
        done();
        this.form.reset();
        this.allocations.set({});
        this.useCredit.set(false);
        this.statement.reload();
        if (this.fromDeposit()) {
          this.deposits.reload();
        }
        this.recorded.emit();
      },
      error: (err: HttpErrorResponse) => {
        this.saveError.set(
          err.status === 409
            ? 'One of the amounts is more than that invoice’s balance due.'
            : err.status === 400
              ? this.fromDeposit()
                ? 'The amounts allocated add up to more than the deposits held.'
                : 'The amounts allocated add up to more than the payment and any credit used.'
              : `Could not ${this.fromDeposit() ? 'apply the deposit' : 'record the payment'}. Please try again.`,
        );
        this.saving.set(false);
        done();
      },
    });
  }

  /** Resolves once any payment being saved has been recorded or refused, so leaving the page does not race it. */
  settled(): Promise<void> {
    return this.inFlight ?? Promise.resolve();
  }

  private format(cents: number): string {
    return this.money.transform(cents / 100, this.currency()) ?? '';
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

/** Money a client has paid against an invoice. */
export interface Payment {
  id: number;
  invoiceId: number;
  amount: number;
  /** ISO date (yyyy-MM-dd) the payment was made. */
  date: string;
}

export interface NewPayment {
  amount: number;
  date: string;
}

/**
 * A lump payment from a client, split across several of their invoices. With `useCredit` the client's credit is used
 * up first; the shares may add up to no more than the amount plus any credit used, and the rest is kept as credit.
 */
export interface NewClientPayment {
  amount: number;
  date: string;
  allocations: { invoiceId: number; amount: number }[];
  useCredit: boolean;
}

/** A recorded lump payment, the credit it used up, what was kept as credit, and the payment it made against each invoice. */
export interface ClientPayment {
  id: number;
  clientId: number;
  amount: number;
  date: string;
  fromDeposits: number;
  fromCreditNotes: number;
  toCredit: number;
  allocations: Payment[];
}

@Injectable({ providedIn: 'root' })
export class PaymentService {
  private readonly http = inject(HttpClient);

  /** An invoice's payments, oldest first. */
  list(projectId: number, invoiceId: number): Observable<Payment[]> {
    return this.http.get<Payment[]>(`/api/projects/${projectId}/invoices/${invoiceId}/payments`);
  }

  record(projectId: number, invoiceId: number, payment: NewPayment): Observable<Payment> {
    return this.http.post<Payment>(`/api/projects/${projectId}/invoices/${invoiceId}/payments`, payment);
  }

  /** Records one lump payment from a client, split across the given invoices. */
  recordForClient(clientId: number, payment: NewClientPayment): Observable<ClientPayment> {
    return this.http.post<ClientPayment>(`/api/clients/${clientId}/payments`, payment);
  }
}

