95	/**
96	 * Keeps the history of exchange rates, and converts foreign amounts into the home currency at the rate in
97	 * effect on a given date.
98	 */
99	@Service
100	public class FxRateService {
101	
102	    private final FxRateRepository rates;
103	    private final CurrencyService currencies;
104	    private final SettingsService settings;
105	    private final Audit audit;
106	
107	    public FxRateService(FxRateRepository rates, CurrencyService currencies, SettingsService settings, Audit audit) {
108	        this.rates = rates;
109	        this.currencies = currencies;
110	        this.settings = settings;
111	        this.audit = audit;
112	    }
