114	    /** The recorded rates, by currency with the most recent first. */
115	    @Transactional(readOnly = true)
116	    public List<FxRateResponse> list() {
117	        return rates.findAllByOrderByCurrencyAscRateDateDescIdDesc().stream().map(FxRateResponse::from).toList();
118	    }
