120	    /**
121	     * Records the currency's rate from the date, recording it in the audit log. A currency has at most one
122	     * rate a day, and the home currency needs none.
123	     */
124	    @Transactional
125	    public FxRateResponse record(FxRateRequest request) {
126	        String currency = request.currency().trim().toUpperCase(Locale.ROOT);
127	        if (!currencies.exists(currency)) {
128	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Unknown currency");
129	        }
130	        if (currency.equals(settings.homeCurrency())) {
131	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The home currency needs no exchange rate");
132	        }
133	        if (rates.existsByCurrencyAndRateDate(currency, request.date())) {
134	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A rate for this currency on this date already exists");
135	        }
136	        FxRate saved = rates.saveAndFlush(new FxRate(currency, request.date(), request.rate()));
137	        audit.record("FX_RATE_RECORDED id=" + saved.getId() + " currency=" + currency + " date=" + saved.getRateDate()
138	                + " rate=" + saved.getRate().stripTrailingZeros().toPlainString());
139	        return FxRateResponse.from(saved);
140	    }
