144	     * on or before it); empty when the currency has no rate by then.
145	     */
146	    @Transactional(readOnly = true)
147	    public Optional<BigDecimal> toHome(String currency, LocalDate date, BigDecimal amount) {
148	        return rates.findFirstByCurrencyAndRateDateLessThanEqualOrderByRateDateDesc(currency, date)
149	                .map(r -> amount.multiply(r.getRate()).setScale(2, RoundingMode.HALF_UP));
150	    }
