-- Money a client has paid against an invoice: how much and on what day. An invoice can be paid in
-- several instalments; payments are financial records, so they block deleting their invoice.
CREATE TABLE payment (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    invoice_id BIGINT         NOT NULL,
    amount     DECIMAL(12, 2) NOT NULL,
    paid_date  DATE           NOT NULL,
    CONSTRAINT payment_invoice_fk FOREIGN KEY (invoice_id) REFERENCES invoice (id),
    CONSTRAINT payment_amount_positive CHECK (amount > 0)
);

CREATE INDEX payment_invoice_idx ON payment (invoice_id, paid_date);
-- A lump sum a client pays in one go, split across several of their invoices. Each share is still
-- recorded as an ordinary payment against its invoice, linked back to the lump it came from.
CREATE TABLE client_payment (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id BIGINT         NOT NULL,
    amount    DECIMAL(12, 2) NOT NULL,
    paid_date DATE           NOT NULL,
    CONSTRAINT client_payment_client_fk FOREIGN KEY (client_id) REFERENCES client (id),
    CONSTRAINT client_payment_amount_positive CHECK (amount > 0)
);

CREATE INDEX client_payment_client_idx ON client_payment (client_id, paid_date);

ALTER TABLE payment ADD COLUMN client_payment_id BIGINT;
ALTER TABLE payment ADD CONSTRAINT payment_client_payment_fk
    FOREIGN KEY (client_payment_id) REFERENCES client_payment (id);
-- A lump payment can now use up the client's credit first: part of what it settles may come out of their held
-- deposits (from_deposits) and then their unused credit notes (from_credit_notes), on top of the money received.
-- Whatever of the money received is not needed for the invoices is kept as credit for the client (to_credit) and
-- is held alongside their deposits. The payments recorded against the invoices always add up to
-- amount + from_deposits + from_credit_notes - to_credit.
ALTER TABLE client_payment ADD COLUMN from_deposits DECIMAL(12, 2) DEFAULT 0 NOT NULL;
ALTER TABLE client_payment ADD COLUMN from_credit_notes DECIMAL(12, 2) DEFAULT 0 NOT NULL;
ALTER TABLE client_payment ADD COLUMN to_credit DECIMAL(12, 2) DEFAULT 0 NOT NULL;
ALTER TABLE client_payment ADD CONSTRAINT client_payment_credit_split CHECK (from_deposits >= 0
    AND from_credit_notes >= 0 AND to_credit >= 0 AND to_credit <= amount);
-- The currencies clients can be billed in, each with the symbol its amounts are shown with and the step
-- its amounts are rounded to when shown (0.01 rounds to the cent; 0.05 to the nearest five cents).
CREATE TABLE currency (
    code VARCHAR(3) PRIMARY KEY,
    symbol VARCHAR(8) NOT NULL,
    rounding_step DECIMAL(10, 2) DEFAULT 0.01 NOT NULL,
    CONSTRAINT currency_rounding_step_positive CHECK (rounding_step > 0)
);

INSERT INTO currency (code, symbol, rounding_step) VALUES
    ('USD', '$', 0.01),
    ('EUR', '€', 0.01),
    ('GBP', '£', 0.01),
    ('CAD', 'CA$', 0.01),
    ('AUD', 'A$', 0.01);

-- A client's currency is now any known currency rather than a fixed list.
ALTER TABLE client DROP CONSTRAINT client_currency_known;
ALTER TABLE client ADD CONSTRAINT client_currency_fk FOREIGN KEY (currency) REFERENCES currency (code);
-- The number of decimal places each currency's amounts are shown with (yen has none); existing
-- currencies keep two.
ALTER TABLE currency ADD COLUMN decimals INT DEFAULT 2 NOT NULL;
ALTER TABLE currency ADD CONSTRAINT currency_decimals_range CHECK (decimals BETWEEN 0 AND 4);
-- The home currency foreign invoices are converted into for the business's own totals; existing data
-- keeps US dollars.
ALTER TABLE app_settings ADD COLUMN home_currency VARCHAR(3) DEFAULT 'USD' NOT NULL;
ALTER TABLE app_settings ADD CONSTRAINT app_settings_home_currency_fk FOREIGN KEY (home_currency) REFERENCES currency (code);

-- Exchange rates by date: one unit of the currency is worth this many units of the home currency from
-- the rate date until the next rate for that currency. An invoice converts at the rate in effect on its
-- issue date.
CREATE TABLE fx_rate (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    currency VARCHAR(3) NOT NULL,
    rate_date DATE NOT NULL,
    rate DECIMAL(19, 6) NOT NULL,
    CONSTRAINT fx_rate_currency_fk FOREIGN KEY (currency) REFERENCES currency (code),
    CONSTRAINT fx_rate_one_per_day UNIQUE (currency, rate_date),
    CONSTRAINT fx_rate_positive CHECK (rate > 0)
);
package net.officefloor.hq.app.fx;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.currency.CurrencyService;
import net.officefloor.hq.app.settings.SettingsService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Keeps the history of exchange rates, and converts foreign amounts into the home currency at the rate in
 * effect on a given date.
 */
@Service
public class FxRateService {

    private final FxRateRepository rates;
    private final CurrencyService currencies;
    private final SettingsService settings;
    private final Audit audit;

    public FxRateService(FxRateRepository rates, CurrencyService currencies, SettingsService settings, Audit audit) {
        this.rates = rates;
        this.currencies = currencies;
        this.settings = settings;
        this.audit = audit;
    }

    /** The recorded rates, by currency with the most recent first. */
    @Transactional(readOnly = true)
    public List<FxRateResponse> list() {
        return rates.findAllByOrderByCurrencyAscRateDateDescIdDesc().stream().map(FxRateResponse::from).toList();
    }

    /**
     * Records the currency's rate from the date, recording it in the audit log. A currency has at most one
     * rate a day, and the home currency needs none.
     */
    @Transactional
    public FxRateResponse record(FxRateRequest request) {
        String currency = request.currency().trim().toUpperCase(Locale.ROOT);
        if (!currencies.exists(currency)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Unknown currency");
        }
        if (currency.equals(settings.homeCurrency())) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The home currency needs no exchange rate");
        }
        if (rates.existsByCurrencyAndRateDate(currency, request.date())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A rate for this currency on this date already exists");
        }
        FxRate saved = rates.saveAndFlush(new FxRate(currency, request.date(), request.rate()));
        audit.record("FX_RATE_RECORDED id=" + saved.getId() + " currency=" + currency + " date=" + saved.getRateDate()
                + " rate=" + saved.getRate().stripTrailingZeros().toPlainString());
        return FxRateResponse.from(saved);
    }

    /**
     * The amount in the home currency, converted at the currency's rate on the date (its latest rate dated
     * on or before it); empty when the currency has no rate by then.
     */
    @Transactional(readOnly = true)
    public Optional<BigDecimal> toHome(String currency, LocalDate date, BigDecimal amount) {
        return rates.findFirstByCurrencyAndRateDateLessThanEqualOrderByRateDateDesc(currency, date)
                .map(r -> amount.multiply(r.getRate()).setScale(2, RoundingMode.HALF_UP));
    }
}
